SELECT '==USUARIOS DE LOS ARCHIVOS RECUPERABLES - ?EN GRUPO 660?==' as '';
SELECT f.id, f.itemid AS deleted_assign_id, u.id AS student_id, u.username AS cedula, u.firstname, u.lastname, f.filename, f.filesize, gm.groupid AS grupo FROM isi_files f JOIN isi_user u ON u.id = f.userid LEFT JOIN isi_groups_members gm ON gm.userid = u.id AND gm.groupid IN (660, 661) WHERE f.component = 'assignsubmission_file' AND f.filename <> '.' AND f.contextid IN (SELECT id FROM isi_context WHERE contextlevel = 70 AND instanceid = 74) AND f.itemid IN (96, 97, 98, 99, 165, 257, 500, 65, 544, 735) ORDER BY f.itemid, u.id;
SELECT '==ESTUDIANTES EN GRUPO 660 (9503)==' as '';
SELECT u.id, u.firstname, u.lastname, u.username AS cedula FROM isi_groups_members gm JOIN isi_user u ON u.id = gm.userid WHERE gm.groupid = 660 ORDER BY u.id;
SELECT '==GRADE_ITEMS_HISTORY PARA ASIGN 257 Y 500 (revisar categoria)==' as '';
SELECT action, oldid, itemname, iteminstance, categoryid, from_unixtime(timemodified) dt FROM isi_grade_items_history WHERE iteminstance IN (257, 500) ORDER BY oldid, id DESC LIMIT 20;
SELECT '==?EXISTEN ACTIVIDADES ACTIVAS EQUIVALENTES EN GRUPO 660? PARA ASSIGN 257==' as '';
SELECT 'Actividad 257 era "Mi Vuelo Digital"' AS info;
SELECT cm.id, cm.section, s.name, cm.instance, a.name FROM isi_course_modules cm JOIN isi_course_sections s ON s.id = cm.section LEFT JOIN isi_assign a ON a.id = cm.instance WHERE cm.course = 74 AND cm.section = 924 AND (a.name LIKE '%Vuelo%Digital%' OR a.name LIKE '%Mi Vuelo%');
SELECT '==?EXISTEN ACTIVIDADES ACTIVAS EQUIVALENTES PARA ASSIGN 500 (Proyecto Final)?==' as '';
SELECT cm.id, cm.section, s.name, cm.instance, a.name FROM isi_course_modules cm JOIN isi_course_sections s ON s.id = cm.section LEFT JOIN isi_assign a ON a.id = cm.instance WHERE cm.course = 74 AND cm.section = 924 AND a.name LIKE '%Proyecto Final%';
SELECT '==SUBMISSIONS PARA ACTIVIDADES ACTIVAS EQUIVALENTES (assign 255 y 502) - USUARIOS DE LOS ARCHIVOS==' as '';
SELECT 'Submission para assign 255 (Vuelo Digital) de user 2602 (Sarahi):' AS info;
SELECT s.id, s.userid, s.status, from_unixtime(s.timecreated) tc FROM isi_assign_submission s WHERE s.assignment = 255 AND s.userid = 2602 AND s.latest = 1;
SELECT 'Submission para assign 502 (PROYECTO FINAL) de user 2587 (Kiara):' AS info;
SELECT s.id, s.userid, s.status, from_unixtime(s.timecreated) tc FROM isi_assign_submission s WHERE s.assignment = 502 AND s.userid = 2587 AND s.latest = 1;
